  if (error.error_subcode !== undefined) parts.push('subcode=' + error.error_subcode)
  if (error.fbtrace_id) parts.push('fbtrace_id=' + error.fbtrace_id)
  return parts.join(' | ') || 'Facebook Graph API lỗi'
}

