  const imgEvalCode =
    'var contentSel = ' + JSON.stringify(contentSel) + ';' +
    'var marker = null;' +
    'try {' +
    '  var markerResult = document.evaluate(contentSel, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null);' +
    '  marker = markerResult.singleNodeValue;' +
    '} catch(e) {}' +
    'if (!marker) return [];' +
    'var candidates = [];' +
    'var node = marker;' +
    'var depth = 0;' +
    'while (node && node !== document.body && depth < 20) {' +
    '  if (node.nodeType === 1 && node.tagName === "DIV" && node.getAttribute("dir") === "auto") {' +
    '    candidates.push(node);' +
    '  }' +
    '  node = node.parentElement;' +
    '  depth++;' +
    '}' +
    'var relativeImageXPath = "./following-sibling::*[1]/div[1]//img";' +
    'var srcs = [];' +
    'for (var c = 0; c < candidates.length; c++) {' +
    '  var r = document.evaluate(relativeImageXPath, candidates[c], null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);' +
    '  if (r.snapshotLength === 0) continue;' +
    '  for (var i = 0; i < r.snapshotLength && srcs.length < 10; i++) {' +
    '    var el = r.snapshotItem(i);' +
    '    var src = el.src || el.getAttribute("src");' +
    '    if (src && src.indexOf("data:") !== 0) srcs.push(src);' +
    '  }' +
    '  break;' +
    '}' +
    'return srcs;'

  let imgSrcs = []
  try { imgSrcs = await page.evaluate(imgEvalCode) || [] } catch (e) {}
  helpers.log('📷 Tìm thấy ' + imgSrcs.length + ' URL ảnh, đang tải về...')

  for (const src of imgSrcs) {
    if (signal.aborted) break
    try {
      const dl = await page.downloadUrl(src, { timeout: 30000 })
      if (dl && dl.filePath) {
        scrapedImages.push(dl.filePath)
      }
    } catch (e) {
      helpers.log('⚠️ Lỗi tải ảnh: ' + (e.message || e))
    }
  }
  helpers.log('📷 Đã tải ' + scrapedImages.length + '/' + imgSrcs.length + ' ảnh về local')

  // Mutate vars.images: merge ảnh user upload + ảnh scraped (theo thứ tự user trước)
  if (scrapedImages.length > 0) {
    const userImages = Array.isArray(vars.images) ? vars.images : []
    vars.images = userImages.concat(scrapedImages)
  }
}

if (typeof helpers.prepareCampaignContent === 'function') {
  vars.campaignSourceText = scrapedText
  vars.campaignSourceMedia = scrapedImages
  return { scrapedText, scrapedImages, sourceContent: scrapedText }
}

helpers.log('📋 Scrape: ' + scrapedText.length + ' ký tự + ' + scrapedImages.length + ' ảnh từ ' + link)
return formattedContentEnabled
